out=[]
for rid,s,e,i in rows:
 assert len(s)==len(e)==6
 out.append({'id':rid,'scores':dict(zip(keys,s)),'total':sum(s),'evidence':dict(zip(keys,e)),'issues':i,'ats_status':'not_tested','fit_status':'provisional','verification_status':'self_report_only','confidence':'medium'})
Path('resume_calibration/secondary_v2.json').write_text(json.dumps(out,ensure_ascii=False,indent=2))
print('Wrote',len(out),'individually evaluated v2 records.')
